 async function loadSubjects(){try{let s=await api<Subject[]>("/subjects");setSubjects(s);let saved=localStorage.getItem("omnilearn.subject");let id=s.some(x=>x.id===saved)&&saved?saved:s[0]?.id||"";setSubject(id);if(!id)setBusy(false)}catch(e:any){setError(`API unavailable: ${e.message}. Start the app with Docker Compose, then refresh.`);setBusy(false)}}
