 async function copyPrompt(kind:string,fromImport=false){
  let subjectName=current?.title||"your learning subject";
  let schema:any;
  let context="";
  if(kind==="initial"){
   schema={subject_id:"my_subject",subject_title:"Name your subject",target_level:"Target level",description:"Short subject description",nodes:[{id:"lesson_01",title:"First lesson",level:"Target level",order_index:0,prerequisites:[],content_markdown:"Lesson content goes here.",test_ids:[]}],tests:[],cards:[],readings:[]};
   context="Create a useful initial learning bundle for "+subjectName+". Include a clear subject_title and at least 3 complete roadmap nodes with substantial lesson content_markdown; do not leave nodes empty. Add useful linked tests, vocabulary cards, or readings when appropriate. Use unique IDs and the supplied bundle structure.";
  }else if(kind==="roadmap"){
   schema={subject_id:subject,subject_title:subjectName,target_level:current?.target_level,nodes:[{id:"node_01",title:"Milestone title",level:current?.target_level,prerequisites:[],content_markdown:"# Lesson content",test_ids:[]}]};
   context="Create a well-sequenced curriculum for "+subjectName+".";
  }else if(kind==="vocab"){
   schema={subject_id:subject,cards:[{id:"word_01",term:"word or phrase",part_of_speech:"part of speech",definition:"clear meaning",example_sentence:"Natural example",image_url:null,tags:["topic"]}]};
   context="Prepare useful vocabulary for "+subjectName+" at "+(current?.target_level||"the appropriate level")+". Topic: "+(vocabTopic==="All words"?"choose a topic":vocabTopic)+".";
  }else if(kind==="reading"){
   schema={subject_id:subject,readings:[{id:"reading_01",title:"Passage title",cefr_level:current?.target_level||"B2",content:"Passage text in Markdown",audio_url:null,questions:[{id:"reading_question_01",prompt:"Question",options:["A","B","C","D"],correct_index:0,explanation:"Evidence from the passage",order_index:0}]}]};
   context="Create an engaging reading comprehension passage for "+subjectName+" at "+(current?.target_level||"the appropriate level")+".";
  }else{
   let lesson=activeNode;
   schema={subject_id:subject,tests:[{id:"question_01",node_id:lesson?.id||null,tags:["topic"],prompt:"Question",options:["A","B","C","D"],correct_index:0,explanation:"Explain why the answer is correct and why each distractor is wrong."}]};
   context="Create assessment questions for "+subjectName+(lesson?" lesson "+lesson.title:"")+"."+(lesson?"\nLESSON MATERIAL (use this as the source; do not test facts absent from it):\n"+lesson.content_markdown:"");
  }
  let prompt="Act as an expert educator and learning-material designer. "+context+"\nReturn only valid JSON, with no Markdown fences or explanation. Match this schema exactly:\n"+JSON.stringify(schema,null,2)+"\nUse unique IDs. Keep every correct_index zero-based and within options. Give clear explanations for every answer.";
  if(kind==="initial")prompt+="\n\nYOUR SUBJECT AND LEARNING GOALS:\n[Describe what you want to learn, your current level, goals, and topics to include.]";
  if(kind==="vocab")prompt+="\n\nUSER TOPIC, SOURCE MATERIAL, OR REQUIRED WORDS:\n[Write a topic, paste source content, or list the exact vocabulary you want included here.]";
  try{await navigator.clipboard.writeText(prompt);message("Prompt copied. Edit its request section before using it.")}catch{if(fromImport){setPromptForImport(prompt);message("Clipboard access is blocked. Copy the prompt text shown here.")}else{setModal("prompt");(window as any).omniprompt=prompt}}
 } async function copyPromptForImport(){let kind=subjects.length===0?"initial":page==="lesson"||page==="lesson-test"||page==="tests"?"test":page==="vocabulary"||page==="vocabulary-practice"?"vocab":page==="readings"?"reading":"roadmap";await copyPrompt(kind,true)}
 async function submitAnswer(q:Test,radio:number|undefined){if(radio===undefined){message("Choose an answer first.");return}await call(async()=>{let result=await api<any>(`/tests/${q.id}/attempts`,json("POST",{selected_index:radio}));setAnswers(a=>({...a,[q.id]:radio}));setRevealed(true);if(result.is_correct)message("Correct! "+result.explanation);else message("Review the explanation below.")})}
